// A: streaming. Addresses are known in advance.
long sum_array(const long *a, size_t n) {
    long s = 0;
    for (size_t i = 0; i < n; i++) s += a[i];
    return s;
}

// B: pointer chasing. The next address is inside the current node.
struct node { struct node *next; long val; };
long sum_list(const struct node *p) {
    long s = 0;
    while (p) { s += p->val; p = p->next; }
    return s;
}

#define D 8
long gather_sum(const long *table, const int *idx, size_t n) {
    long s = 0;
    for (size_t i = 0; i < n; i++) {
        if (i + D < n)
            __builtin_prefetch(&table[idx[i + D]], 0, 3);
        s += table[idx[i]];
    }
    return s;
}

#include <emmintrin.h>

/* Fill one 64-byte line with byte c, bypassing the cache.
   p must be 16-byte aligned; ideally 64-byte aligned. */
void setline(char *p, int c) {
    __m128i v = _mm_set1_epi8((char)c);
    _mm_stream_si128((__m128i *)&p[0],  v);
    _mm_stream_si128((__m128i *)&p[16], v);
    _mm_stream_si128((__m128i *)&p[32], v);
    _mm_stream_si128((__m128i *)&p[48], v);
}
